{
  "name": "SHFQA量子分析仪",
  "name_en": "SHFQA Quantum Analyzer",
  "manufacturer": "Zurich Instruments",
  "description": "这是一台 Zurich Instruments 的 SHFQA 量子分析仪，用于量子测量实验中的读出脉冲生成、采集控制、加权积分、DIO 触发联动以及谱学配置。驱动表明该设备支持测量序列上传、外部时钟锁定、采集单元控制、积分权重配置和串扰校正，常用于超导量子比特读出与相关表征实验。",
  "description_en": "This is a Zurich Instruments SHFQA quantum analyzer used in quantum measurement experiments for readout pulse generation, acquisition control, weighted integration, DIO-triggered coordination, and spectroscopy setup. The driver indicates support for sequencer program upload, external clock locking, acquisition unit control, integration weight configuration, and crosstalk correction, making it suitable for superconducting qubit readout and related characterization experiments.",
  "actions": [
    {
      "action_name": "auto-load_default_settings",
      "description": "加载设备参数的默认设置到驱动缓存中，但不立即下发到仪器。",
      "description_en": "Load default parameter settings into the driver cache without immediately uploading them to the instrument."
    },
    {
      "action_name": "auto-configure_awg_from_string",
      "description": "向指定测序器上传并配置字符串形式的 SeqC/AWG 程序。",
      "description_en": "Upload and configure a SeqC/AWG program string to the specified sequencer."
    },
    {
      "action_name": "auto-assure_ext_clock",
      "description": "尝试将仪器锁定到外部参考时钟。",
      "description_en": "Attempt to lock the instrument to an external reference clock."
    },
    {
      "action_name": "auto-clock_freq",
      "description": "读取设备时钟频率。",
      "description_en": "Read the device clock frequency."
    },
    {
      "action_name": "auto-plot_dio_snapshot",
      "description": "绘制数字 I/O 位快照，用于触发与时序诊断。",
      "description_en": "Plot a digital I/O bit snapshot for trigger and timing diagnostics."
    },
    {
      "action_name": "auto-acquisition",
      "description": "执行一次完整采集流程，并返回测量结果。",
      "description_en": "Run a complete acquisition procedure and return the measurement results."
    },
    {
      "action_name": "auto-acquisition_initialize",
      "description": "按给定测量参数初始化采集单元和通道配置。",
      "description_en": "Initialize the acquisition units and channel setup with the specified measurement parameters."
    },
    {
      "action_name": "auto-acquisition_arm",
      "description": "使采集系统进入等待触发的就绪状态。",
      "description_en": "Arm the acquisition system so it is ready for triggering."
    },
    {
      "action_name": "auto-acquisition_poll",
      "description": "通过轮询方式读取已完成采集的结果。",
      "description_en": "Retrieve completed acquisition results using a polling method."
    },
    {
      "action_name": "auto-acquisition_get",
      "description": "通过获取接口读取已完成采集的结果。",
      "description_en": "Retrieve completed acquisition results using the get interface."
    },
    {
      "action_name": "auto-acquisition_finalize",
      "description": "结束并收尾当前测量采集流程。",
      "description_en": "Finalize and clean up the current measurement acquisition procedure."
    },
    {
      "action_name": "auto-snapshot_base",
      "description": "返回设备及其参数配置的快照信息。",
      "description_en": "Return a snapshot of the instrument and its parameter configuration."
    },
    {
      "action_name": "auto-awg_sequence_acquisition_and_DIO_triggered_pulse",
      "description": "配置由 DIO 触发的采集与读出脉冲序列，用于码字类实验。",
      "description_en": "Configure a DIO-triggered acquisition and readout pulse sequence for codeword-style experiments."
    },
    {
      "action_name": "auto-awg_sequence_acquisition_and_pulse",
      "description": "配置单量子比特实验中的读出脉冲与采集序列，可选数字触发。",
      "description_en": "Configure a readout pulse and acquisition sequence for single-qubit experiments, optionally with digital triggering."
    },
    {
      "action_name": "auto-awg_sequence_acquisition",
      "description": "配置仅执行触发采集而不输出读出脉冲的序列。",
      "description_en": "Configure a sequence that performs triggered acquisition without outputting a readout pulse."
    },
    {
      "action_name": "auto-awg_sequence_acquisition_and_pulse_SSB",
      "description": "配置带单边带调制读出脉冲的采集序列。",
      "description_en": "Configure an acquisition sequence with a single-sideband modulated readout pulse."
    },
    {
      "action_name": "auto-configure_spectroscopy",
      "description": "配置连续或脉冲式谱学扫描实验序列。",
      "description_en": "Configure a continuous or pulsed spectroscopy sweep experiment sequence."
    },
    {
      "action_name": "auto-awg_sequence_acquisition_and_DIO_RED_test",
      "description": "配置用于 DIO 触发与时序验证的测试采集序列。",
      "description_en": "Configure a test acquisition sequence for DIO triggering and timing verification."
    },
    {
      "action_name": "auto-awg_sequence_test_pattern",
      "description": "输出测序器测试图样，用于接口与时序检查。",
      "description_en": "Output a sequencer test pattern for interface and timing checks."
    },
    {
      "action_name": "auto-spec_mode_on",
      "description": "开启谱学测量模式并设置相关采集参数。",
      "description_en": "Enable spectroscopy mode and set the related acquisition parameters."
    },
    {
      "action_name": "auto-prepare_SSB_weight_and_rotation",
      "description": "上传单边带积分权重并设置读出旋转参数。",
      "description_en": "Upload single-sideband integration weights and set the readout rotation parameters."
    },
    {
      "action_name": "auto-prepare_DSB_weight_and_rotation",
      "description": "上传双边带积分权重并设置相应旋转参数。",
      "description_en": "Upload double-sideband integration weights and set the corresponding rotation parameters."
    },
    {
      "action_name": "auto-output_dio_calibration_data",
      "description": "输出 DIO 校准数据或模式，用于数字接口校准。",
      "description_en": "Output DIO calibration data or patterns for digital interface calibration."
    },
    {
      "action_name": "auto-calibrate_dio_protocol",
      "description": "根据期望序列校准 DIO 协议与时序。",
      "description_en": "Calibrate the DIO protocol and timing against an expected sequence."
    },
    {
      "action_name": "auto-active_slots",
      "description": "返回当前驱动配置中启用的槽位列表。",
      "description_en": "Return the list of active slots in the current driver configuration."
    },
    {
      "action_name": "auto-active_channels",
      "description": "返回当前驱动配置中启用的通道列表。",
      "description_en": "Return the list of active channels in the current driver configuration."
    },
    {
      "action_name": "auto-validate_config",
      "description": "校验当前缓存的设备配置是否有效。",
      "description_en": "Validate whether the currently cached device configuration is valid."
    },
    {
      "action_name": "auto-push_to_device",
      "description": "将驱动中缓存的配置下发到实际仪器。",
      "description_en": "Push the configuration cached in the driver to the physical instrument."
    },
    {
      "action_name": "auto-reset_acquisition_params",
      "description": "重置采集相关参数。",
      "description_en": "Reset acquisition-related parameters."
    },
    {
      "action_name": "auto-reset_user_registers",
      "description": "重置用户寄存器。",
      "description_en": "Reset the user registers."
    },
    {
      "action_name": "auto-reset_crosstalk_matrix",
      "description": "重置串扰校正矩阵。",
      "description_en": "Reset the crosstalk correction matrix."
    },
    {
      "action_name": "auto-reset_correlation_params",
      "description": "重置相关性分析参数。",
      "description_en": "Reset correlation analysis parameters."
    },
    {
      "action_name": "auto-reset_rotation_params",
      "description": "重置积分或读出旋转参数。",
      "description_en": "Reset integration or readout rotation parameters."
    },
    {
      "action_name": "auto-upload_crosstalk_matrix",
      "description": "上传串扰校正矩阵到设备配置中。",
      "description_en": "Upload a crosstalk correction matrix into the device configuration."
    },
    {
      "action_name": "auto-download_crosstalk_matrix",
      "description": "读取当前串扰校正矩阵。",
      "description_en": "Read back the current crosstalk correction matrix."
    },
    {
      "action_name": "auto-print_correlation_overview",
      "description": "打印相关性参数概览。",
      "description_en": "Print an overview of the correlation parameters."
    },
    {
      "action_name": "auto-print_deskew_overview",
      "description": "打印去偏斜设置概览。",
      "description_en": "Print an overview of the deskew settings."
    },
    {
      "action_name": "auto-print_crosstalk_overview",
      "description": "打印串扰配置概览。",
      "description_en": "Print an overview of the crosstalk configuration."
    },
    {
      "action_name": "auto-print_integration_overview",
      "description": "打印积分设置概览。",
      "description_en": "Print an overview of the integration settings."
    },
    {
      "action_name": "auto-print_rotations_overview",
      "description": "打印旋转参数概览。",
      "description_en": "Print an overview of the rotation parameters."
    },
    {
      "action_name": "auto-print_thresholds_overview",
      "description": "打印阈值设置概览。",
      "description_en": "Print an overview of the threshold settings."
    },
    {
      "action_name": "auto-print_user_regs_overview",
      "description": "打印用户寄存器概览。",
      "description_en": "Print an overview of the user registers."
    },
    {
      "action_name": "auto-print_overview",
      "description": "打印设备整体配置概览。",
      "description_en": "Print an overall overview of the device configuration."
    }
  ],
  "tag_hints": [
    "qubit readout",
    "quantum analyzer",
    "AWG sequencer",
    "microwave spectroscopy",
    "weighted integration",
    "DIO triggering",
    "crosstalk correction",
    "external reference clock"
  ]
}

